function User({ name, role }) {
  return <li>{name} · {role}</li>
}
function App() {
  const user = { name: '小明', role: '前端' }
  return <ul><User name={user.name} role={user.role} /></ul>
}

function TodoList({ items }) {
  if (items.length === 0) return <p>暂无待办</p>
  return <ul>{items.map(t => <li key={t.id}>{t.text}</li>)}</ul>
}

// 推荐：用稳定的业务 id
{items.map(t => <li key={t.id}>{t.text}</li>)}
// 反例：插入到头部时 index 全部错位
{items.map((t, i) => <li key={i}>{t.text}</li>)}

function Card({ title, children }) {
  return <div className="card"><h3>{title}</h3>{children}</div>
}
